import { useState, useEffect } from 'react';
import { useNavigate } from 'react-router-dom';
import { motion } from 'framer-motion';
import { ArrowRight, ExternalLink, Wrench } from 'lucide-react';
import { supabase } from '../lib/supabase';

const Tools = ({ showCount }) => {
  const [tools, setTools] = useState([]);
  const [loading, setLoading] = useState(true);
  const navigate = useNavigate();

  useEffect(() => {
    loadTools();
  }, []);

  const loadTools = async () => {
    try {
      const { data, error } = await supabase
        .from('tools')
        .select('*')
        .or('status.eq.active,status.is.null')
        .order('sort_order', { ascending: true });
      if (error) throw error;
      setTools(data || []);
    } catch (err) {
      console.error('Load tools error:', err);
      setTools([]);
    }
    setLoading(false);
  };

  const displayTools = showCount ? tools.slice(0, showCount) : tools;

  return (
    <section id="tools" className="py-20 px-4 sm:px-6 lg:px-8">
      <div className="max-w-6xl mx-auto">
        <motion.div
          initial={{ opacity: 0, y: 20 }}
          whileInView={{ opacity: 1, y: 0 }}
          viewport={{ once: true }}
          transition={{ duration: 0.6 }}
          className="text-center mb-12"
        >
          <h2 className="text-3xl sm:text-4xl font-bold mb-4">
            <span className="bg-gradient-to-r from-purple-400 to-pink-400 bg-clip-text text-transparent">工具箱</span>
          </h2>
          <p className="text-white/60 max-w-2xl mx-auto">精选实用工具，提升开发效率</p>
        </motion.div>

        {loading ? (
          <div className="flex items-center justify-center py-12">
            <div className="animate-spin w-8 h-8 border-2 border-purple-500 border-t-transparent rounded-full" />
          </div>
        ) : displayTools.length === 0 ? (
          <div className="text-center py-12 text-white/40">
            <Wrench className="w-12 h-12 mx-auto mb-4 opacity-50" />
            <p>暂无工具</p>
          </div>
        ) : (
          <>
            <div className="grid grid-cols-1 sm:grid-cols-2 lg:grid-cols-3 xl:grid-cols-4 gap-6">
              {displayTools.map((tool, index) => (
                <motion.a
                  key={tool.id}
                  href={tool.url || '#'}
                  target="_blank"
                  rel="noopener noreferrer"
                  initial={{ opacity: 0, y: 20 }}
                  whileInView={{ opacity: 1, y: 0 }}
                  viewport={{ once: true }}
                  transition={{ duration: 0.5, delay: index * 0.05 }}
                  className="group bg-white/5 backdrop-blur-sm rounded-2xl border border-white/10 p-6 hover:bg-white/10 hover:border-purple-500/30 transition-all duration-300 hover:-translate-y-1"
                >
                  <div className="text-4xl mb-4">{tool.icon || '🔧'}</div>
                  <h3 className="text-lg font-semibold text-white mb-2 group-hover:text-purple-400 transition-colors">
                    {tool.name}
                  </h3>
                  <p className="text-white/50 text-sm mb-4 line-clamp-2">{tool.description || '暂无描述'}</p>
                  <div className="flex items-center text-purple-400 text-sm opacity-0 group-hover:opacity-100 transition-opacity">
                    <span>使用工具</span>
                    <ExternalLink className="w-4 h-4 ml-1" />
                  </div>
                </motion.a>
              ))}
            </div>

            {showCount && tools.length > showCount && (
              <motion.div
                initial={{ opacity: 0 }}
                whileInView={{ opacity: 1 }}
                viewport={{ once: true }}
                className="text-center mt-10"
              >
                <button
                  onClick={() => navigate('/tools')}
                  className="inline-flex items-center gap-2 px-6 py-3 rounded-xl bg-white/5 border border-white/10 text-white/60 hover:text-white hover:bg-white/10 transition-all"
                >
                  查看全部工具
                  <ArrowRight className="w-4 h-4" />
                </button>
              </motion.div>
            )}
          </>
        )}
      </div>
    </section>
  );
};

export default Tools;
