import { useState, useEffect } from 'react';
import { motion } from 'framer-motion';
import { ArrowUp, ChevronRight } from 'lucide-react';
import ParticleBackground from './ParticleBackground';
import Navigation from './Navigation';
import Footer from './Footer';

/**
 * 公共页面布局组件
 * @param {Object} props
 * @param {React.ReactNode} props.children - 页面内容
 * @param {Array<{label: string, onClick?: () => void, icon?: React.ReactNode}>} props.breadcrumbs - 面包屑导航数组
 * @param {boolean} props.showBackToTop - 是否显示回到顶部按钮，默认 true
 */
export default function PageLayout({ children, breadcrumbs = [], showBackToTop = true }) {
  const [visibleBackToTop, setVisibleBackToTop] = useState(false);

  useEffect(() => {
    if (!showBackToTop) return;
    const handleScroll = () => {
      setVisibleBackToTop(window.scrollY > 300);
    };
    window.addEventListener('scroll', handleScroll, { passive: true });
    return () => window.removeEventListener('scroll', handleScroll);
  }, [showBackToTop]);

  const scrollToTop = () => {
    window.scrollTo({ top: 0, behavior: 'smooth' });
  };

  return (
    <div className="min-h-screen bg-[#0a0a0f] text-white">
      <ParticleBackground />
      <Navigation />

      <main className="relative z-10 pt-24 pb-20">
        {/* 面包屑导航 */}
        {breadcrumbs.length > 0 && (
          <div className="max-w-6xl mx-auto px-6">
            <motion.div
              initial={{ opacity: 0, y: -10 }}
              animate={{ opacity: 1, y: 0 }}
              className="flex items-center gap-2 text-sm text-white/50 mb-8"
            >
              {breadcrumbs.map((item, index) => (
                <span key={index} className="flex items-center gap-2">
                  {index > 0 && <ChevronRight className="w-3 h-3 text-white/30" />}
                  {item.onClick ? (
                    <motion.button
                      onClick={item.onClick}
                      className="flex items-center gap-1 hover:text-purple-400 transition-colors"
                      whileHover={{ scale: 1.02 }}
                    >
                      {item.icon && <span className="flex items-center">{item.icon}</span>}
                      <span>{item.label}</span>
                    </motion.button>
                  ) : (
                    <span className="text-white/70 truncate max-w-[200px]">{item.label}</span>
                  )}
                </span>
              ))}
            </motion.div>
          </div>
        )}

        {children}
      </main>

      {/* 回到顶部按钮 */}
      {showBackToTop && (
        <motion.button
          initial={{ opacity: 0, scale: 0.8 }}
          animate={{ opacity: visibleBackToTop ? 1 : 0, scale: visibleBackToTop ? 1 : 0 }}
          onClick={scrollToTop}
          className="fixed bottom-8 right-8 z-50 w-12 h-12 rounded-full bg-gradient-to-r from-purple-500 to-pink-500 shadow-lg shadow-purple-500/30 flex items-center justify-center text-white hover:shadow-xl hover:shadow-purple-500/40 transition-shadow"
          whileHover={{ scale: 1.1, y: -2 }}
          whileTap={{ scale: 0.95 }}
          title="回到顶部"
        >
          <ArrowUp className="w-5 h-5" />
        </motion.button>
      )}

      <Footer />
    </div>
  );
}
