import { useState, useEffect } from 'react';
import { motion } from 'framer-motion';
import { ExternalLink, Eye, ArrowRight, ChevronLeft, ChevronRight, Home } from 'lucide-react';
import { useNavigate } from 'react-router-dom';
import { supabase } from '../lib/supabase';
import ScrollReveal from '../components/ScrollReveal';
import GlassCard from '../components/GlassCard';
import PageLayout from '../components/PageLayout';

// 自定义GitHub图标
const GithubIcon = ({ className }) => (
  <svg className={className} viewBox="0 0 24 24" fill="currentColor">
    <path d="M12 0c-6.626 0-12 5.373-12 12 0 5.302 3.438 9.8 8.207 11.387.599.111.793-.261.793-.577v-2.234c-3.338.726-4.033-1.416-4.033-1.416-.546-1.387-1.333-1.756-1.333-1.756-1.089-.745.083-.729.083-.729 1.205.084 1.839 1.237 1.839 1.237 1.07 1.834 2.807 1.304 3.492.997.107-.775.418-1.305.762-1.604-2.665-.305-5.467-1.334-5.467-5.931 0-1.311.469-2.381 1.236-3.221-.124-.303-.535-1.524.117-3.176 0 0 1.008-.322 3.301 1.23.957-.266 1.983-.399 3.003-.404 1.02.005 2.047.138 3.006.404 2.291-1.552 3.297-1.23 3.297-1.23.653 1.653.242 2.874.118 3.176.77.84 1.235 1.911 1.235 3.221 0 4.609-2.807 5.624-5.479 5.921.43.372.823 1.102.823 2.222v3.293c0 .319.192.694.801.576 4.765-1.589 8.199-6.086 8.199-11.386 0-6.627-5.373-12-12-12z"/>
  </svg>
);

const PROJECTS_PER_PAGE = 6;

const PortfolioList = () => {
  const navigate = useNavigate();
  const [currentPage, setCurrentPage] = useState(1);
  const [projects, setProjects] = useState([]);
  const [loading, setLoading] = useState(true);

  useEffect(() => {
    loadPortfolios();
  }, []);

  const loadPortfolios = async () => {
    try {
      const { data, error } = await supabase
        .from('portfolios')
        .select('*')
        .or('status.eq.active,status.is.null')
        .order('sort_order', { ascending: true });

      if (error) throw error;

      // 转换数据格式
      const formattedProjects = (data || []).map(item => ({
        id: item.id,
        title: item.title,
        description: item.description,
        image: item.image_url || 'https://images.unsplash.com/photo-1460925895917-afdab827c52f?w=800&h=600&fit=crop',
        tags: item.technologies || [],
        demoUrl: item.demo_url || '#',
        githubUrl: item.github_url || '#',
        color: 'rgba(102, 126, 234, 0.3)',
      }));

      setProjects(formattedProjects);
    } catch (err) {
      console.error('Load portfolios error:', err);
      setProjects([]);
    }
    setLoading(false);
  };

  const totalCount = projects.length;
  const totalPages = Math.ceil(totalCount / PROJECTS_PER_PAGE);

  // 获取当前页的项目
  const getCurrentPageProjects = () => {
    const from = (currentPage - 1) * PROJECTS_PER_PAGE;
    const to = from + PROJECTS_PER_PAGE;
    return projects.slice(from, to);
  };

  const handlePageChange = (page) => {
    if (page >= 1 && page <= totalPages) {
      setCurrentPage(page);
      window.scrollTo({ top: 0, behavior: 'smooth' });
    }
  };

  // 恢复滚动位置
  useEffect(() => {
    const saved = sessionStorage.getItem('home_scroll_position');
    if (saved) {
      // 在列表页不需要恢复，清除即可
      sessionStorage.removeItem('home_scroll_position');
    }
    window.scrollTo(0, 0);
  }, []);

  // 面包屑导航
  const breadcrumbs = [
    {
      label: '首页',
      icon: <Home className="w-4 h-4" />,
      onClick: () => {
        sessionStorage.setItem('home_scroll_position', '0');
        navigate('/');
        setTimeout(() => {
          window.scrollTo({ top: 0, behavior: 'smooth' });
        }, 100);
      }
    },
    { label: '作品集' }
  ];

  return (
    <PageLayout breadcrumbs={breadcrumbs}>
      <div className="max-w-6xl mx-auto px-6">
        {/* 页面标题 */}
        <ScrollReveal className="text-center mb-12">
          <span className="text-purple-400 text-sm font-medium tracking-wider uppercase mb-4 block">
            Portfolio
          </span>
          <h1 className="text-4xl md:text-5xl font-bold text-white mb-6">
            精选作品
          </h1>
          <p className="text-white/60 text-lg max-w-2xl mx-auto">
            探索我的创意项目，每一个都是技术与艺术的结合，共 {totalCount} 个作品
          </p>
        </ScrollReveal>

        {/* 加载状态 */}
        {loading ? (
          <div className="flex items-center justify-center py-20">
            <div className="animate-spin w-8 h-8 border-2 border-purple-500 border-t-transparent rounded-full" />
          </div>
        ) : (
          <>
            {/* 项目网格 */}
            <div className="grid md:grid-cols-2 lg:grid-cols-3 gap-8">
              {getCurrentPageProjects().map((project, index) => (
                <ScrollReveal key={project.id} delay={index * 0.1}>
                  <GlassCard
                    className="group overflow-hidden h-full"
                    glowColor={project.color}
                  >
                    {/* 图片容器 */}
                    <div className="relative h-48 overflow-hidden">
                      <motion.img
                        src={project.image}
                        alt={project.title}
                        className="w-full h-full object-cover"
                        whileHover={{ scale: 1.1 }}
                        transition={{ duration: 0.6 }}
                      />
                      {/* 悬停遮罩 */}
                      <motion.div
                        className="absolute inset-0 bg-black/60 flex items-center justify-center gap-4 opacity-0 group-hover:opacity-100 transition-opacity duration-300"
                      >
                        {project.demoUrl && project.demoUrl !== '#' && (
                        <motion.a
                          href={project.demoUrl}
                          target="_blank"
                          rel="noopener noreferrer"
                          className="p-3 rounded-full bg-white/20 backdrop-blur-sm text-white hover:bg-white/30 transition-colors"
                          whileHover={{ scale: 1.1 }}
                          whileTap={{ scale: 0.95 }}
                        >
                          <Eye className="w-5 h-5" />
                        </motion.a>
                        )}
                        <motion.a
                          href={project.githubUrl}
                          target="_blank"
                          rel="noopener noreferrer"
                          className="p-3 rounded-full bg-white/20 backdrop-blur-sm text-white hover:bg-white/30 transition-colors"
                          whileHover={{ scale: 1.1 }}
                          whileTap={{ scale: 0.95 }}
                        >
                          <GithubIcon className="w-5 h-5" />
                        </motion.a>
                      </motion.div>
                    </div>

                    {/* 内容 */}
                    <div className="p-6">
                      <h3 className="text-xl font-semibold text-white mb-2 group-hover:text-purple-400 transition-colors">
                        {project.title}
                      </h3>
                      <p className="text-white/60 text-sm mb-4 line-clamp-2">
                        {project.description}
                      </p>

                      {/* 标签 */}
                      <div className="flex flex-wrap gap-2">
                        {(Array.isArray(project.tags) ? project.tags : []).map((tag, tagIndex) => (
                          <span
                            key={tagIndex}
                            className="px-3 py-1 text-xs rounded-full bg-white/5 text-white/70 border border-white/10"
                          >
                            {tag}
                          </span>
                        ))}
                      </div>
                    </div>

                    {/* 底部装饰线 */}
                    <div
                      className="absolute bottom-0 left-0 h-1 bg-gradient-to-r from-purple-500 to-pink-500 transition-all duration-300 w-0 group-hover:w-full"
                    />
                  </GlassCard>
                </ScrollReveal>
              ))}
            </div>

            {/* 分页 */}
            {totalPages > 1 && (
              <ScrollReveal delay={0.3}>
                <div className="flex items-center justify-center gap-2 mt-12">
                  <motion.button
                    onClick={() => handlePageChange(currentPage - 1)}
                    disabled={currentPage === 1}
                    className="p-2 rounded-lg bg-white/5 text-white/60 hover:text-white disabled:opacity-30 disabled:cursor-not-allowed transition-colors"
                    whileHover={{ scale: 1.05 }}
                    whileTap={{ scale: 0.95 }}
                  >
                    <ChevronLeft className="w-5 h-5" />
                  </motion.button>

                  {Array.from({ length: Math.min(totalPages, 7) }, (_, i) => {
                    let page;
                    if (totalPages <= 7) {
                      page = i + 1;
                    } else if (currentPage <= 4) {
                      page = i + 1;
                    } else if (currentPage >= totalPages - 3) {
                      page = totalPages - 6 + i;
                    } else {
                      page = currentPage - 3 + i;
                    }
                    return (
                      <motion.button
                        key={page}
                        onClick={() => handlePageChange(page)}
                        className={`w-10 h-10 rounded-lg font-medium transition-colors ${
                          page === currentPage
                            ? 'bg-purple-500 text-white'
                            : 'bg-white/5 text-white/60 hover:text-white'
                        }`}
                        whileHover={{ scale: 1.05 }}
                        whileTap={{ scale: 0.95 }}
                      >
                        {page}
                      </motion.button>
                    );
                  })}

                  <motion.button
                    onClick={() => handlePageChange(currentPage + 1)}
                    disabled={currentPage === totalPages}
                    className="p-2 rounded-lg bg-white/5 text-white/60 hover:text-white disabled:opacity-30 disabled:cursor-not-allowed transition-colors"
                    whileHover={{ scale: 1.05 }}
                    whileTap={{ scale: 0.95 }}
                  >
                    <ChevronRight className="w-5 h-5" />
                  </motion.button>
                </div>

                <p className="text-center text-white/40 text-sm mt-4">
                  第 {currentPage} / {totalPages} 页，共 {totalCount} 个作品
                </p>
              </ScrollReveal>
            )}
          </>
        )}

        {/* 返回首页 */}
        <div className="text-center mt-12">
          <motion.button
            onClick={() => navigate('/')}
            className="inline-flex items-center gap-2 text-purple-400 hover:text-purple-300 transition-colors"
            whileHover={{ x: -5 }}
          >
            <ArrowRight className="w-4 h-4 rotate-180" />
            返回首页
          </motion.button>
        </div>
      </div>
    </PageLayout>
  );
};

export default PortfolioList;
