import { useState, useEffect } from 'react';
import { useParams, useNavigate } from 'react-router-dom';
import { motion } from 'framer-motion';
import { Calendar, Clock, Share2, Bookmark, Eye, Check, Copy, Home, BookOpen, ArrowLeft } from 'lucide-react';
import { supabase } from '../lib/supabase';
import PageLayout from '../components/PageLayout';
import DOMPurify from 'dompurify';
import { formatDate, calcReadTime, formatViews } from '../utils/formatUtils';

export default function PostDetail() {
  const [post, setPost] = useState(null);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState('');
  const [isBookmarked, setIsBookmarked] = useState(false);
  const [showShareMenu, setShowShareMenu] = useState(false);
  const [copySuccess, setCopySuccess] = useState(false);
  const { id: postId } = useParams();
  const navigate = useNavigate();

  useEffect(() => {
    if (postId) {
      loadPost();
      checkBookmark();
    }
  }, [postId]);

  const loadPost = async () => {
    try {
      // 增加浏览量
      const { data: postData } = await supabase
        .from('posts')
        .select('*')
        .eq('id', postId)
        .single();

      if (!postData) {
        setError('文章不存在');
        setLoading(false);
        return;
      }

      // 计算新的浏览量
      const newViews = (postData.views || 0) + 1;

      // 直接UPDATE查询增加浏览量（更可靠）
      await supabase
        .from('posts')
        .update({ views: newViews })
        .eq('id', postId);

      // 同时更新UI
      setPost({ ...postData, views: newViews });
    } catch (err) {
      console.error('Load post error:', err);
      setError('加载失败');
    }
    setLoading(false);
  };

  const checkBookmark = () => {
    let bookmarks = [];
    try { bookmarks = JSON.parse(localStorage.getItem('wuyinqingshan_bookmarks') || '[]'); } catch(e) { bookmarks = []; }
    setIsBookmarked(bookmarks.includes(postId));
  };

  const toggleBookmark = async () => {
    let bookmarks = [];
    try { bookmarks = JSON.parse(localStorage.getItem('wuyinqingshan_bookmarks') || '[]'); } catch(e) { bookmarks = []; }
    let newBookmarks;

    if (isBookmarked) {
      newBookmarks = bookmarks.filter(id => id !== postId);
    } else {
      newBookmarks = [...bookmarks, postId];
      // 保存到数据库
      try {
        await supabase.from('bookmarks').upsert({
          user_id: localStorage.getItem('wuyinqingshan_visitor_id'),
          post_id: postId,
          created_at: new Date().toISOString()
        });
      } catch (err) {
        console.error('Bookmark save error:', err);
      }
    }

    localStorage.setItem('wuyinqingshan_bookmarks', JSON.stringify(newBookmarks));
    setIsBookmarked(!isBookmarked);
  };

  const copyLink = async () => {
    const url = window.location.href;
    try {
      await navigator.clipboard.writeText(url);
      setCopySuccess(true);
      setTimeout(() => setCopySuccess(false), 2000);
    } catch (err) {
      // 降级方案
      const textArea = document.createElement('textarea');
      textArea.value = url;
      document.body.appendChild(textArea);
      textArea.select();
      document.execCommand('copy');
      document.body.removeChild(textArea);
      setCopySuccess(true);
      setTimeout(() => setCopySuccess(false), 2000);
    }
    setShowShareMenu(false);
  };

  const shareToTwitter = () => {
    const text = `${post?.title} - 雾隐青山博客`;
    const url = window.location.href;
    window.open(`https://twitter.com/intent/tweet?text=${encodeURIComponent(text)}&url=${encodeURIComponent(url)}`, '_blank');
    setShowShareMenu(false);
  };

  const shareToWeibo = () => {
    const text = `${post?.title} - 雾隐青山博客`;
    const url = window.location.href;
    window.open(`https://service.weibo.com/share/share.php?title=${encodeURIComponent(text)}&url=${encodeURIComponent(url)}`, '_blank');
    setShowShareMenu(false);
  };

  // 渲染内容（支持富文本 HTML 和旧版 Markdown）
  const renderContent = (content) => {
    if (!content) return '';
    
    // 处理 Markdown 代码块（```...```）
    let processedContent = content
      .replace(/```(\w+)?\n([\s\S]*?)```/g, (match, lang, code) => {
        const escapedCode = code
          .replace(/&/g, '&amp;')
          .replace(/</g, '&lt;')
          .replace(/>/g, '&gt;');
        return `<pre class="code-block"><code>${escapedCode}</code></pre>`;
      })
      // 内联代码样式
      .replace(/`([^`]+)`/g, '<code class="inline-code">$1</code>');
    
    // 如果内容包含 HTML 标签（但不是我们刚刚添加的代码块），直接净化
    if (/<[a-z][\s\S]*>/i.test(processedContent) && !processedContent.includes('class="code-block"')) {
      return DOMPurify.sanitize(processedContent);
    }
    
    // 否则，继续处理 Markdown 格式
    let html = processedContent
      .replace(/^### (.*$)/gim, '<h3>$1</h3>')
      .replace(/^## (.*$)/gim, '<h2>$1</h2>')
      .replace(/^# (.*$)/gim, '<h1>$1</h1>')
      .replace(/^\- (.*$)/gim, '<li>$1</li>')
      .replace(/\[([^\]]+)\]\(([^)]+)\)/g, '<a href="$2" target="_blank" rel="noopener">$1</a>')
      .replace(/\*\*([^*]+)\*\*/g, '<strong>$1</strong>')
      .replace(/\*([^*]+)\*/g, '<em>$1</em>')
      .replace(/\n\n/g, '</p><p>')
      .replace(/\n/g, '<br/>');
    
    return `<p>${html}</p>`;
  };

  // 面包屑导航
  const breadcrumbs = [
    {
      label: '首页',
      icon: <Home className="w-4 h-4" />,
      onClick: () => {
        sessionStorage.setItem('home_scroll_position', '0');
        navigate('/');
        setTimeout(() => {
          const blogSection = document.getElementById('blog');
          if (blogSection) {
            blogSection.scrollIntoView({ behavior: 'smooth' });
          } else {
            window.scrollTo({ top: 0, behavior: 'smooth' });
          }
        }, 100);
      }
    },
    {
      label: '博客',
      icon: <BookOpen className="w-4 h-4" />,
      onClick: () => {
        const savedScrollPos = sessionStorage.getItem('bloglist_scroll_position');
        navigate('/blog');
        if (savedScrollPos) {
          setTimeout(() => {
            window.scrollTo(0, parseInt(savedScrollPos, 10));
            sessionStorage.removeItem('bloglist_scroll_position');
          }, 100);
        }
      }
    },
    { label: post?.title }
  ];

  if (loading) {
    return (
      <div className="min-h-screen bg-[#0a0a0f] flex items-center justify-center">
        <div className="animate-spin w-8 h-8 border-2 border-purple-500 border-t-transparent rounded-full" />
      </div>
    );
  }

  if (error || !post) {
    return (
      <div className="min-h-screen bg-[#0a0a0f] flex items-center justify-center">
        <div className="text-center">
          <p className="text-white/60 mb-4">{error || '文章不存在'}</p>
          <button onClick={() => navigate('/')} className="text-purple-400 hover:text-purple-300">
            返回首页
          </button>
        </div>
      </div>
    );
  }

  return (
    <PageLayout breadcrumbs={breadcrumbs}>
      <article className="max-w-4xl mx-auto px-6">
        {/* 返回按钮 */}
        <motion.div
          initial={{ opacity: 0, x: -20 }}
          animate={{ opacity: 1, x: 0 }}
          className="mb-6"
        >
          <button
            onClick={() => {
              // 检查是否有来源信息
              const fromPage = sessionStorage.getItem('bloglist_page');
              if (fromPage) {
                navigate('/blog');
              } else {
                // 如果没有缓存，返回首页博客区块
                sessionStorage.setItem('home_scroll_position', '0');
                navigate('/');
                setTimeout(() => {
                  const blogSection = document.getElementById('blog');
                  if (blogSection) {
                    blogSection.scrollIntoView({ behavior: 'smooth' });
                  }
                }, 100);
              }
            }}
            className="inline-flex items-center gap-2 text-white/60 hover:text-white transition-colors group"
          >
            <ArrowLeft className="w-5 h-5 transition-transform group-hover:-translate-x-1" />
            <span>返回博客列表</span>
          </button>
        </motion.div>

        {/* 文章头部 */}
        <motion.header
          initial={{ opacity: 0, y: 20 }}
          animate={{ opacity: 1, y: 0 }}
          className="mb-12"
        >
          {/* 分类和标签 */}
          <div className="flex flex-wrap items-center gap-2 mb-4">
            <span className="inline-block px-3 py-1 text-sm font-medium rounded-full bg-purple-500/20 text-purple-400">
              {post.category || '技术'}
            </span>
            {(() => {
              let tags = post.tags;
              if (typeof tags === 'string') {
                try {
                  tags = JSON.parse(tags);
                } catch {
                  tags = tags.split(',').map(t => t.trim());
                }
              }
              if (!Array.isArray(tags)) tags = [];
              return tags.map((tag, i) => (
                <span key={i} className="px-2 py-0.5 text-xs rounded-full bg-white/5 text-white/60">
                  {tag}
                </span>
              ));
            })()}
          </div>

          {/* 标题 */}
          <h1 className="text-2xl md:text-3xl font-bold text-white mb-6 leading-tight">
            {post.title}
          </h1>

          {/* 元信息 */}
          <div className="flex flex-wrap items-center gap-6 text-white/50 text-sm">
            <span className="flex items-center gap-2">
              <Calendar className="w-4 h-4" />
              {formatDate(post.created_at)}
            </span>
            <span className="flex items-center gap-2">
              <Clock className="w-4 h-4" />
              {calcReadTime(post.content)}
            </span>
            <span className="flex items-center gap-2">
              <Eye className="w-4 h-4" />
              {formatViews(post.views)} 次阅读
            </span>
          </div>
        </motion.header>

        {/* 封面图 */}
        {(post.image || post.cover_image) && (
          <motion.div
            initial={{ opacity: 0, scale: 0.95 }}
            animate={{ opacity: 1, scale: 1 }}
            transition={{ delay: 0.2 }}
            className="mb-12 rounded-2xl overflow-hidden"
          >
            <img
              src={post.image || post.cover_image}
              alt={post.title}
              className="w-full h-64 md:h-96 object-cover"
            />
          </motion.div>
        )}

        {/* 文章内容 */}
        <motion.div
          initial={{ opacity: 0, y: 20 }}
          animate={{ opacity: 1, y: 0 }}
          transition={{ delay: 0.3 }}
          className="max-w-none"
        >
          <div
            className="text-white/80 leading-relaxed text-sm md:text-base
              [&_h1]:text-lg [&_h1]:md:text-xl [&_h1]:font-bold [&_h1]:text-white [&_h1]:mt-6 [&_h1]:mb-3
              [&_h2]:text-base [&_h2]:md:text-lg [&_h2]:font-bold [&_h2]:text-white [&_h2]:mt-5 [&_h2]:mb-2
              [&_h3]:text-sm [&_h3]:md:text-base [&_h3]:font-bold [&_h3]:text-white [&_h3]:mt-4 [&_h3]:mb-2
              [&_p]:text-white/80 [&_p]:leading-relaxed [&_p]:mb-3 [&_p]:text-sm [&_p]:md:text-base
              [&_a]:text-purple-400 [&_a:hover]:text-purple-300
              [&_ul]:list-disc [&_ul]:ml-6 [&_ul]:mb-3 [&_ul]:text-white/80 [&_ul]:text-sm [&_ul]:md:text-base
              [&_ol]:list-decimal [&_ol]:ml-6 [&_ol]:mb-3 [&_ol]:text-white/80 [&_ol]:text-sm [&_ol]:md:text-base
              [&_li]:mb-1 [&_li]:text-sm [&_li]:md:text-base
              [&_blockquote]:border-l-4 [&_blockquote]:border-purple-500 [&_blockquote]:pl-4 [&_blockquote]:italic [&_blockquote]:text-white/60 [&_blockquote]:my-3
              [&_img]:rounded-lg [&_img]:my-3 [&_img]:max-w-full
              [&_strong]:font-bold [&_strong]:text-white
              [&_em]:italic
              [&_table]:w-full [&_table]:border-collapse [&_table]:my-3
              [&_th]:border [&_th]:border-white/10 [&_th]:px-2 [&_th]:py-1 [&_th]:text-left [&_th]:text-white/90 [&_th]:text-xs
              [&_td]:border [&_td]:border-white/10 [&_td]:px-2 [&_td]:py-1 [&_td]:text-white/70 [&_td]:text-xs
              [&_div]:text-sm [&_div]:md:text-base [&_div]:leading-relaxed
              [&_span]:text-sm [&_span]:md:text-base
              [&_section]:text-sm [&_section]:md:text-base
              [&_article]:text-sm [&_article]:md:text-base
              [&_pre]:bg-[#1a1a2e] [&_pre]:rounded-lg [&_pre]:p-3 [&_pre]:my-3 [&_pre]:overflow-x-auto [&_pre]:border [&_pre]:border-white/10
              [&_pre_h1]:text-xs [&_pre_h1]:font-mono [&_pre_h1]:text-gray-300 [&_pre_h1]:m-0 [&_pre_h1]:font-normal
              [&_pre_h2]:text-xs [&_pre_h2]:font-mono [&_pre_h2]:text-gray-300 [&_pre_h2]:m-0 [&_pre_h2]:font-normal
              [&_pre_h3]:text-xs [&_pre_h3]:font-mono [&_pre_h3]:text-gray-300 [&_pre_h3]:m-0 [&_pre_h3]:font-normal
              [&_pre_code]:text-xs [&_pre_code]:leading-relaxed [&_pre_code]:text-gray-300 [&_pre_code]:font-mono
              [&_pre_span]:text-xs [&_pre_span]:font-mono [&_pre_span]:text-gray-300
              [&_pre_div]:text-xs [&_pre_div]:font-mono [&_pre_div]:text-gray-300
              [&_pre_p]:text-xs [&_pre_p]:font-mono [&_pre_p]:text-gray-300 [&_pre_p]:m-0
              [&_.code-block]:bg-[#1a1a2e] [&_.code-block]:rounded-lg [&_.code-block]:p-3 [&_.code-block]:my-3 [&_.code-block]:overflow-x-auto [&_.code-block]:border [&_.code-block]:border-white/10
              [&_.code-block_h1]:text-xs [&_.code-block_h1]:font-mono [&_.code-block_h1]:text-gray-300 [&_.code-block_h1]:m-0 [&_.code-block_h1]:font-normal
              [&_.code-block_h2]:text-xs [&_.code-block_h2]:font-mono [&_.code-block_h2]:text-gray-300 [&_.code-block_h2]:m-0 [&_.code-block_h2]:font-normal
              [&_.code-block_h3]:text-xs [&_.code-block_h3]:font-mono [&_.code-block_h3]:text-gray-300 [&_.code-block_h3]:m-0 [&_.code-block_h3]:font-normal
              [&_.code-block_code]:text-xs [&_.code-block_code]:leading-relaxed [&_.code-block_code]:text-gray-300 [&_.code-block_code]:font-mono
              [&_.code-block_span]:text-xs [&_.code-block_span]:font-mono [&_.code-block_span]:text-gray-300
              [&_.code-block_div]:text-xs [&_.code-block_div]:font-mono [&_.code-block_div]:text-gray-300
              [&_.code-block_p]:text-xs [&_.code-block_p]:font-mono [&_.code-block_p]:text-gray-300 [&_.code-block_p]:m-0
              [&_.inline-code]:bg-white/10 [&_.inline-code]:text-purple-300 [&_.inline-code]:px-1.5 [&_.inline-code]:py-0.5 [&_.inline-code]:rounded [&_.inline-code]:text-xs [&_.inline-code]:font-mono
              [&_code]:text-xs [&_code]:font-mono [&_code]:text-gray-300"
            dangerouslySetInnerHTML={{ __html: renderContent(post.content) }}
          />
        </motion.div>

        {/* 文章底部操作 */}
        <motion.div
          initial={{ opacity: 0 }}
          animate={{ opacity: 1 }}
          transition={{ delay: 0.5 }}
          className="mt-12 pt-8 border-t border-white/10 flex items-center justify-between flex-wrap gap-4"
        >
          {/* 分享按钮 */}
          <div className="relative">
            <motion.button
              onClick={() => setShowShareMenu(!showShareMenu)}
              className="flex items-center gap-2 px-4 py-2 rounded-lg bg-white/5 text-white/60 hover:text-white hover:bg-white/10 transition-colors"
              whileHover={{ scale: 1.02 }}
              whileTap={{ scale: 0.98 }}
            >
              <Share2 className="w-4 h-4" />
              <span>分享</span>
            </motion.button>

            {showShareMenu && (
              <motion.div
                initial={{ opacity: 0, y: 10 }}
                animate={{ opacity: 1, y: 0 }}
                className="absolute bottom-full left-0 mb-2 w-48 bg-[#1a1a2e] rounded-lg border border-white/10 shadow-xl overflow-hidden"
              >
                <button
                  onClick={copyLink}
                  className="flex items-center gap-3 w-full px-4 py-3 text-white/80 hover:bg-white/5 transition-colors"
                >
                  {copySuccess ? <Check className="w-4 h-4 text-green-400" /> : <Copy className="w-4 h-4" />}
                  <span>{copySuccess ? '已复制!' : '复制链接'}</span>
                </button>
                <button
                  onClick={shareToTwitter}
                  className="flex items-center gap-3 w-full px-4 py-3 text-white/80 hover:bg-white/5 transition-colors"
                >
                  <span className="text-lg">𝕏</span>
                  <span>分享到 Twitter</span>
                </button>
                <button
                  onClick={shareToWeibo}
                  className="flex items-center gap-3 w-full px-4 py-3 text-white/80 hover:bg-white/5 transition-colors"
                >
                  <span className="text-lg">📧</span>
                  <span>分享到微博</span>
                </button>
              </motion.div>
            )}
          </div>

          {/* 收藏按钮 */}
          <motion.button
            onClick={toggleBookmark}
            className={`flex items-center gap-2 px-4 py-2 rounded-lg transition-colors ${
              isBookmarked
                ? 'bg-purple-500/20 text-purple-400'
                : 'bg-white/5 text-white/60 hover:text-white hover:bg-white/10'
            }`}
            whileHover={{ scale: 1.02 }}
            whileTap={{ scale: 0.98 }}
          >
            <Bookmark className={`w-4 h-4 ${isBookmarked ? 'fill-current' : ''}`} />
            <span>{isBookmarked ? '已收藏' : '收藏'}</span>
          </motion.button>
        </motion.div>

        {/* 版权声明 */}
        <motion.div
          initial={{ opacity: 0 }}
          animate={{ opacity: 1 }}
          transition={{ delay: 0.6 }}
          className="mt-12 p-6 rounded-2xl bg-white/5 border border-white/10"
        >
          <p className="text-white/60 text-sm">
            <strong className="text-white">版权声明：</strong>
            本文来源互联网整理，仅供学习交流。如有侵权，请联系删除。
          </p>
          <p className="text-white/40 text-xs mt-2">
            最后更新：{formatDate(post.updated_at || post.created_at)}
          </p>
        </motion.div>
      </article>
    </PageLayout>
  );
}
