import { useState, useEffect } from 'react';
import { motion } from 'framer-motion';
import { Calendar, Clock, ArrowRight, BookOpen, Eye, ChevronLeft, ChevronRight, Home } from 'lucide-react';
import { useNavigate } from 'react-router-dom';
import ScrollReveal from '../components/ScrollReveal';
import GlassCard from '../components/GlassCard';
import SafeImage from '../components/SafeImage';
import PageLayout from '../components/PageLayout';
import { supabase } from '../lib/supabase';
import { formatDateShort, formatRelativeTime, formatViews } from '../utils/formatUtils';

const POSTS_PER_PAGE = 6;

const BlogList = () => {
  const [posts, setPosts] = useState([]);
  const [loading, setLoading] = useState(true);
  const [currentPage, setCurrentPage] = useState(1);
  const [totalCount, setTotalCount] = useState(0);
  const [isRestoring, setIsRestoring] = useState(true); // 标记是否正在恢复状态
  const navigate = useNavigate();

  const totalPages = Math.ceil(totalCount / POSTS_PER_PAGE);

  // 恢复分页状态
  useEffect(() => {
    const savedPage = sessionStorage.getItem('bloglist_page');
    
    if (savedPage) {
      setCurrentPage(parseInt(savedPage, 10));
    }
    
    setIsRestoring(false);
  }, []);

  // 数据加载完成后恢复滚动位置
  useEffect(() => {
    if (!loading && posts.length > 0) {
      const savedScrollPos = sessionStorage.getItem('bloglist_scroll_position');
      if (savedScrollPos) {
        setTimeout(() => {
          window.scrollTo(0, parseInt(savedScrollPos, 10));
          sessionStorage.removeItem('bloglist_scroll_position');
        }, 100);
      }
    }
  }, [loading, posts]);

  useEffect(() => {
    // 如果正在恢复状态（初始加载），跳过数据加载
    // 等待页码恢复后再加载数据
    if (isRestoring) return;
    loadPosts();
  }, [currentPage, isRestoring]);

  const loadPosts = async () => {
    try {
      setLoading(true);
      const from = (currentPage - 1) * POSTS_PER_PAGE;
      const to = from + POSTS_PER_PAGE - 1;

      const { data, count, error } = await supabase
        .from('posts')
        .select('*', { count: 'exact' })
        .eq('status', 'published')
        .order('created_at', { ascending: false })
        .range(from, to);

      if (error) throw error;
      setPosts(data || []);
      setTotalCount(count || 0);
    } catch (err) {
      console.error('Load posts error:', err);
    }
    setLoading(false);
  };

  const handlePageChange = (page) => {
    if (page >= 1 && page <= totalPages) {
      setCurrentPage(page);
      // 保存当前页码
      sessionStorage.setItem('bloglist_page', page.toString());
      window.scrollTo({ top: 0, behavior: 'smooth' });
    }
  };

  // 点击文章时保存状态
  const handlePostClick = (postId) => {
    sessionStorage.setItem('bloglist_page', currentPage.toString());
    sessionStorage.setItem('bloglist_scroll_position', window.scrollY.toString());
    navigate(`/post/${postId}`);
  };

  // 面包屑导航
  const breadcrumbs = [
    {
      label: '首页',
      icon: <Home className="w-4 h-4" />,
      onClick: () => {
        sessionStorage.setItem('home_scroll_position', '0');
        navigate('/');
        setTimeout(() => {
          window.scrollTo({ top: 0, behavior: 'smooth' });
        }, 100);
      }
    },
    { label: '博客' }
  ];

  return (
    <PageLayout breadcrumbs={breadcrumbs}>
      <div className="max-w-6xl mx-auto px-6">
        {/* 页面标题 */}
        <ScrollReveal className="text-center mb-12">
          <span className="text-purple-400 text-sm font-medium tracking-wider uppercase mb-4 block">
            Blog
          </span>
          <h1 className="text-4xl md:text-5xl font-bold text-white mb-6">
            技术博客
          </h1>
          <p className="text-white/60 text-lg max-w-2xl mx-auto">
            追踪技术前沿，分享学习心得，共 {totalCount} 篇文章
          </p>
        </ScrollReveal>

        {/* 文章列表 */}
        {loading ? (
          <div className="flex items-center justify-center py-20">
            <div className="animate-spin w-8 h-8 border-2 border-purple-500 border-t-transparent rounded-full" />
          </div>
        ) : posts.length === 0 ? (
          <div className="text-center py-20 text-white/40">
            <BookOpen className="w-12 h-12 mx-auto mb-4 opacity-50" />
            <p>暂无文章</p>
          </div>
        ) : (
          <>
            <div className="grid md:grid-cols-2 lg:grid-cols-3 gap-8">
              {posts.map((post, index) => (
                <ScrollReveal key={post.id} delay={index * 0.1}>
                  <GlassCard className="group h-full flex flex-col cursor-pointer" onClick={() => handlePostClick(post.id)}>
                    {/* 图片 */}
                    <div className="relative h-48 overflow-hidden rounded-t-2xl">
                      <motion.div whileHover={{ scale: 1.05 }} transition={{ duration: 0.6 }} className="w-full h-full">
                        <SafeImage
                          src={post.image || post.cover_image}
                          alt={post.title}
                          type="post"
                          className="w-full h-full object-cover"
                        />
                      </motion.div>
                      <div className="absolute top-4 left-4 flex gap-2">
                        <span className="px-3 py-1 text-xs font-medium rounded-full bg-black/50 backdrop-blur-sm text-white">
                          {post.category || '技术'}
                        </span>
                      </div>
                    </div>

                    {/* 内容 */}
                    <div className="p-6 flex-1 flex flex-col">
                      <div className="flex items-center gap-4 text-sm text-white/50 mb-3">
                        <span className="flex items-center gap-1">
                          <Calendar className="w-4 h-4" />
                          {formatDateShort(post.created_at)}
                        </span>
                        <span className="flex items-center gap-1">
                          <Clock className="w-4 h-4" />
                          {formatRelativeTime(post.created_at)}
                        </span>
                      </div>

                      <h3 className="text-lg font-semibold text-white mb-2 group-hover:text-purple-400 transition-colors line-clamp-2">
                        {post.title}
                      </h3>

                      <p className="text-white/60 text-sm line-clamp-2 mb-4 flex-1">
                        {post.excerpt || post.content?.substring(0, 100)}
                      </p>

                      {/* 标签和浏览量 */}
                      <div className="flex items-center justify-between mb-3">
                        <div className="flex flex-wrap gap-1">
                          {(() => {
                            let tags = post.tags;
                            if (typeof tags === 'string') {
                              try {
                                tags = JSON.parse(tags);
                              } catch {
                                tags = tags.split(',').map(t => t.trim());
                              }
                            }
                            if (!Array.isArray(tags)) tags = [];
                            return tags.slice(0, 2).map((tag, i) => (
                              <span key={i} className="px-2 py-0.5 text-xs rounded-full bg-purple-500/20 text-purple-400">
                                {tag}
                              </span>
                            ));
                          })()}
                        </div>
                        <span className="flex items-center gap-1 text-white/40 text-sm">
                          <Eye className="w-4 h-4" />
                          {formatViews(post.views)}
                        </span>
                      </div>

                      {/* 阅读全文 */}
                      <motion.button
                        onClick={(e) => {
                          e.stopPropagation();
                          handlePostClick(post.id);
                        }}
                        className="inline-flex items-center gap-2 text-purple-400 text-sm font-medium group/read cursor-pointer"
                        whileHover={{ x: 5 }}
                      >
                        <span>阅读全文</span>
                        <ArrowRight className="w-4 h-4 transition-transform group-hover/read:translate-x-1" />
                      </motion.button>
                    </div>
                  </GlassCard>
                </ScrollReveal>
              ))}
            </div>

            {/* 分页 */}
            {totalPages > 1 && (
              <ScrollReveal delay={0.3}>
                <div className="flex items-center justify-center gap-2 mt-12">
                  <motion.button
                    onClick={() => handlePageChange(currentPage - 1)}
                    disabled={currentPage === 1}
                    className="p-2 rounded-lg bg-white/5 text-white/60 hover:text-white disabled:opacity-30 disabled:cursor-not-allowed transition-colors"
                    whileHover={{ scale: 1.05 }}
                    whileTap={{ scale: 0.95 }}
                  >
                    <ChevronLeft className="w-5 h-5" />
                  </motion.button>

                  {Array.from({ length: Math.min(totalPages, 7) }, (_, i) => {
                    let page;
                    if (totalPages <= 7) {
                      page = i + 1;
                    } else if (currentPage <= 4) {
                      page = i + 1;
                    } else if (currentPage >= totalPages - 3) {
                      page = totalPages - 6 + i;
                    } else {
                      page = currentPage - 3 + i;
                    }
                    return (
                      <motion.button
                        key={page}
                        onClick={() => handlePageChange(page)}
                        className={`w-10 h-10 rounded-lg font-medium transition-colors ${
                          page === currentPage
                            ? 'bg-purple-500 text-white'
                            : 'bg-white/5 text-white/60 hover:text-white'
                        }`}
                        whileHover={{ scale: 1.05 }}
                        whileTap={{ scale: 0.95 }}
                      >
                        {page}
                      </motion.button>
                    );
                  })}

                  <motion.button
                    onClick={() => handlePageChange(currentPage + 1)}
                    disabled={currentPage === totalPages}
                    className="p-2 rounded-lg bg-white/5 text-white/60 hover:text-white disabled:opacity-30 disabled:cursor-not-allowed transition-colors"
                    whileHover={{ scale: 1.05 }}
                    whileTap={{ scale: 0.95 }}
                  >
                    <ChevronRight className="w-5 h-5" />
                  </motion.button>
                </div>

                <p className="text-center text-white/40 text-sm mt-4">
                  第 {currentPage} / {totalPages} 页，共 {totalCount} 篇文章
                </p>
              </ScrollReveal>
            )}
          </>
        )}

        {/* 返回首页 */}
        <div className="text-center mt-12">
          <motion.button
            onClick={() => navigate('/')}
            className="inline-flex items-center gap-2 text-purple-400 hover:text-purple-300 transition-colors"
            whileHover={{ x: -5 }}
          >
            <ArrowRight className="w-4 h-4 rotate-180" />
            返回首页
          </motion.button>
        </div>
      </div>
    </PageLayout>
  );
};

export default BlogList;
