import { useState, useEffect, useRef } from 'react';
import { Routes, Route, HashRouter, useLocation } from 'react-router-dom';
import './styles/animations.css';
import ParticleBackground from './components/ParticleBackground';
import Navigation from './components/Navigation';
import Footer from './components/Footer';
import Hero from './sections/Hero';
import About from './sections/About';
import Portfolio from './sections/Portfolio';
import Blog from './sections/Blog';
import News from './sections/News';
import Contact from './sections/Contact';
import Tools from './sections/Tools';
import PostDetail from './pages/PostDetail';
import BlogList from './pages/BlogList';
import NewsList from './pages/NewsList';
import NewsDetail from './pages/NewsDetail';
import PortfolioList from './pages/PortfolioList';
import ToolsList from './pages/ToolsList';
import ScrollToTop from './components/ScrollToTop';
import { supabase } from './lib/supabase';

// 访问统计追踪组件 - 前台博客
// 使用 HashRouter，所以需要监听 window.location.hash 来获取实际路由
function AnalyticsTracker() {
  const lastRecordTime = useRef(0);
  const lastPath = useRef(localStorage.getItem('wuyinqingshan_last_path') || '');
  const isInitialized = useRef(false);

  useEffect(() => {
    const getCurrentPath = () => {
      // HashRouter 使用 window.location.hash 获取路由
      // 例如：#/blog -> /blog, #/post/123 -> /post/123
      const hash = window.location.hash;
      if (hash && hash.length > 1) {
        return hash.substring(1); // 移除 #
      }
      return '/';
    };

    const recordVisit = async () => {
      try {
        const path = getCurrentPath();
        
        // 避免重复记录相同路径（使用 localStorage 持久化）
        if (path === lastPath.current) {
          return;
        }
        lastPath.current = path;
        localStorage.setItem('wuyinqingshan_last_path', path);

        const visitorId = localStorage.getItem('wuyinqingshan_visitor_id') ||
          'visitor_' + Date.now() + '_' + Math.random().toString(36).substring(2, 9);
        localStorage.setItem('wuyinqingshan_visitor_id', visitorId);

        // 判断访问类型：页面访问(platform) 或 资源访问(resource)
        const isResource = path.startsWith('/post/') || 
                          path.startsWith('/news/') || 
                          path.startsWith('/portfolio/');
        const visitType = isResource ? 'resource' : 'platform';

        const { error } = await supabase.from('visit_logs').insert({
          visitor_id: visitorId,
          visit_type: visitType,
          page_path: path,
          created_at: new Date().toISOString()
        });
        
        if (error) {
          console.error('Visit record failed:', error);
        } else {
          console.log('✅ Visit recorded:', path, visitType);
        }
      } catch (err) {
        console.error('Visit record error:', err);
      }
    };

    // 监听 hashchange 事件（HashRouter 路由变化）
    const handleHashChange = () => {
      const now = Date.now();
      if (now - lastRecordTime.current > 300) { // 300ms 防抖
        lastRecordTime.current = now;
        recordVisit();
      }
    };

    // 页面加载时记录初始路径（使用 setTimeout 确保 hash 已设置）
    setTimeout(() => {
      if (!isInitialized.current) {
        isInitialized.current = true;
        // 初始化时强制记录当前路径
        const path = getCurrentPath();
        lastPath.current = path;
        localStorage.setItem('wuyinqingshan_last_path', path);
        recordVisit();
      }
    }, 100);

    // 监听 hash 变化
    window.addEventListener('hashchange', handleHashChange);
    
    return () => {
      window.removeEventListener('hashchange', handleHashChange);
    };
  }, []);

  return null;
}

// 滚动到锚点的组件
function ScrollToAnchor() {
  const location = useLocation();

  useEffect(() => {
    // 1. 检查 sessionStorage 中保存的锚点（从其他页面导航过来）
    const scrollToSection = sessionStorage.getItem('scroll_to_section');
    if (scrollToSection) {
      sessionStorage.removeItem('scroll_to_section');
      setTimeout(() => {
        const element = document.getElementById(scrollToSection);
        if (element) {
          element.scrollIntoView({ behavior: 'smooth' });
        }
      }, 300);
      return;
    }

    // 2. 检查 URL hash 中的锚点
    const hash = window.location.hash;
    if (hash.includes('#/') && hash.includes('#', 2)) {
      const anchorIndex = hash.indexOf('#', 2);
      if (anchorIndex !== -1) {
        const anchor = hash.substring(anchorIndex + 1);
        const element = document.getElementById(anchor);
        if (element) {
          setTimeout(() => {
            element.scrollIntoView({ behavior: 'smooth' });
          }, 100);
        }
      }
    }
  }, [location]);

  return null;
}

// 前台主页
function Home() {
  const [modules, setModules] = useState(null);

  useEffect(() => {
    const loadModules = async () => {
      const saved = localStorage.getItem('wuyinqingshan_modules');
      if (saved) {
        try {
          const parsed = JSON.parse(saved);
          if (Array.isArray(parsed) && parsed.length > 0 && parsed[0].id) {
            setModules(parsed);
            return;
          }
        } catch {}
      }

      // localStorage 无效或为空，尝试从 Supabase 加载
      try {
        const { data } = await supabase.from('settings').select('value').eq('key', 'modules').single();
        if (data?.value) {
          let modulesData = data.value;
          if (typeof modulesData === 'string') {
            try { modulesData = JSON.parse(modulesData); } catch {}
          }
          if (Array.isArray(modulesData) && modulesData.length > 0 && modulesData[0].id) {
            setModules(modulesData);
            localStorage.setItem('wuyinqingshan_modules', JSON.stringify(modulesData));
            return;
          }
        }
      } catch {}

      // 默认模块配置（确保工具箱始终可用）
      const defaultModules = [
        { id: 'hero', name: 'Hero 横幅', enabled: true, order: 1, showCount: 1 },
        { id: 'about', name: '关于我', enabled: true, order: 2, showCount: 1 },
        { id: 'portfolio', name: '精选作品', enabled: true, order: 3, showCount: 6 },
        { id: 'blog', name: '技术博客', enabled: true, order: 4, showCount: 6 },
        { id: 'news', name: '每日资讯', enabled: true, order: 5, showCount: 6 },
        { id: 'tools', name: '工具箱', enabled: true, order: 6, showCount: 6 },
        { id: 'contact', name: '联系我', enabled: true, order: 7, showCount: 1 },
      ];
      setModules(defaultModules);
      localStorage.setItem('wuyinqingshan_modules', JSON.stringify(defaultModules));
    };

    loadModules();
  }, []);

  // 从列表页返回首页时滚动到之前位置
  useEffect(() => {
    const homeScrollPos = sessionStorage.getItem('home_scroll_position');
    if (homeScrollPos === '0') {
      sessionStorage.removeItem('home_scroll_position');
      window.scrollTo({ top: 0, behavior: 'smooth' });
    }
  }, []);

  const enabledModules = modules
    ? modules.filter(m => m.enabled).sort((a, b) => a.order - b.order)
    : null;

  return (
    <div className="relative min-h-screen bg-[#0a0a0f] text-white overflow-x-hidden">
      <AnalyticsTracker />
      <ParticleBackground />
      <Navigation />
      <main className="relative z-10">
        <section id="home"><Hero /></section>
        {enabledModules ? enabledModules.map(mod => {
          switch(mod.id) {
            case 'about': return <About key="about" />;
            case 'portfolio': return <Portfolio key="portfolio" showCount={mod.showCount} />;
            case 'blog': return <Blog key="blog" showCount={mod.showCount} />;
            case 'news': return <News key="news" showCount={mod.showCount} />;
            case 'tools': return <Tools key="tools" showCount={mod.showCount} />;
            case 'contact': return <Contact key="contact" />;
            default: return null;
          }
        }) : (
          <>
            <About />
            <Portfolio />
            <Blog />
            <News />
            <Tools />
            <Contact />
          </>
        )}
      </main>
      <Footer />
      <ScrollToTop />
    </div>
  );
}

function App() {
  return (
    <HashRouter>
      <ScrollToAnchor />
      <Routes>
        <Route path="/" element={<Home />} />
        <Route path="/post/:id" element={<PostDetail />} />
        <Route path="/blog" element={<BlogList />} />
        <Route path="/news" element={<NewsList />} />
        <Route path="/news/:id" element={<NewsDetail />} />
        <Route path="/portfolio" element={<PortfolioList />} />
        <Route path="/tools" element={<ToolsList />} />
        <Route path="*" element={<Home />} />
      </Routes>
    </HashRouter>
  );
}

export default App;
