/**
 * 统一的格式化工具函数
 * 解决时区和数据格式不一致的问题
 */

/**
 * 格式化日期为 YYYY-MM-DD HH:mm:ss 格式
 * @param {string|Date} dateStr - 日期字符串或Date对象
 * @returns {string} 格式化后的日期字符串
 */
export const formatDate = (dateStr) => {
  if (!dateStr) return '';

  const date = new Date(dateStr);

  // 检查日期是否有效
  if (isNaN(date.getTime())) return '';

  // 使用 Asia/Shanghai 时区
  const year = date.getFullYear();
  const month = String(date.getMonth() + 1).padStart(2, '0');
  const day = String(date.getDate()).padStart(2, '0');
  const hours = String(date.getHours()).padStart(2, '0');
  const minutes = String(date.getMinutes()).padStart(2, '0');
  const seconds = String(date.getSeconds()).padStart(2, '0');

  return `${year}-${month}-${day} ${hours}:${minutes}:${seconds}`;
};

/**
 * 格式化日期为 YYYY-MM-DD 格式（简短）
 * @param {string|Date} dateStr - 日期字符串或Date对象
 * @returns {string} 格式化后的日期字符串
 */
export const formatDateShort = (dateStr) => {
  if (!dateStr) return '';

  const date = new Date(dateStr);

  // 检查日期是否有效
  if (isNaN(date.getTime())) return '';

  // 使用 Asia/Shanghai 时区
  const year = date.getFullYear();
  const month = String(date.getMonth() + 1).padStart(2, '0');
  const day = String(date.getDate()).padStart(2, '0');

  return `${year}-${month}-${day}`;
};

/**
 * 格式化相对时间（几分钟前、几小时前、几天前）
 * @param {string|Date} dateStr - 日期字符串或Date对象
 * @returns {string} 相对时间字符串
 */
export const formatRelativeTime = (dateStr) => {
  if (!dateStr) return '';

  const date = new Date(dateStr);

  // 检查日期是否有效
  if (isNaN(date.getTime())) return '';

  const now = new Date();
  const diff = now - date; // 毫秒差

  // 处理未来时间（可能是时区问题）
  if (diff < 0) {
    return formatDate(dateStr);
  }

  const minutes = Math.floor(diff / 60000);
  const hours = Math.floor(diff / 3600000);
  const days = Math.floor(diff / 86400000);

  if (minutes < 1) return '刚刚';
  if (minutes < 60) return `${minutes} 分钟前`;
  if (hours < 24) return `${hours} 小时前`;
  if (days < 7) return `${days} 天前`;
  if (days < 30) return `${Math.floor(days / 7)} 周前`;

  // 超过30天显示具体日期
  return formatDate(dateStr);
};

/**
 * 格式化浏览量（大数字简化显示）
 * @param {number} views - 浏览量
 * @returns {string} 格式化后的浏览量字符串
 */
export const formatViews = (views) => {
  if (views === null || views === undefined) return '0';

  const num = Number(views);
  if (isNaN(num)) return '0';

  if (num >= 10000) {
    return `${(num / 10000).toFixed(1)}万`;
  }
  if (num >= 1000) {
    return `${(num / 1000).toFixed(1)}k`;
  }
  return num.toString();
};

/**
 * 计算阅读时间
 * @param {string} content - 文章内容
 * @returns {string} 阅读时间字符串
 */
export const calcReadTime = (content) => {
  if (!content) return '3 分钟';

  // 移除HTML标签计算纯文本长度
  const textContent = content.replace(/<[^>]*>/g, '');
  const words = textContent.length;
  const minutes = Math.max(1, Math.ceil(words / 500));

  return `${minutes} 分钟`;
};

export default {
  formatDate,
  formatDateShort,
  formatRelativeTime,
  formatViews,
  calcReadTime
};
