import { useState, useEffect } from 'react';
import { useParams, useNavigate } from 'react-router-dom';
import { motion } from 'framer-motion';
import { Share2, ExternalLink, Calendar, Home, Newspaper, ArrowLeft } from 'lucide-react';
import { supabase } from '../lib/supabase';
import PageLayout from '../components/PageLayout';
import DOMPurify from 'dompurify';
import { formatDateShort, formatDate, formatRelativeTime, formatViews } from '../utils/formatUtils';

export default function NewsDetail() {
  const [news, setNews] = useState(null);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState('');
  const [copySuccess, setCopySuccess] = useState(false);
  const { id: newsId } = useParams();
  const navigate = useNavigate();

  useEffect(() => {
    if (newsId) {
      loadNews();
    }
  }, [newsId]);

  const loadNews = async () => {
    try {
      const { data: newsData, error } = await supabase
        .from('news')
        .select('*')
        .eq('id', newsId)
        .single();

      if (error || !newsData) {
        setError('资讯不存在');
        setLoading(false);
        return;
      }

      // 计算新的浏览量
      const newViews = (newsData.views || 0) + 1;

      // 直接UPDATE查询增加浏览量（更可靠）
      await supabase
        .from('news')
        .update({ views: newViews })
        .eq('id', newsId);

      // 同时更新UI
      setNews({ ...newsData, views: newViews });
    } catch (err) {
      console.error('Load news error:', err);
      setError('加载失败');
    }
    setLoading(false);
  };

  // 面包屑导航
  const breadcrumbs = [
    {
      label: '首页',
      icon: <Home className="w-4 h-4" />,
      onClick: () => {
        sessionStorage.setItem('home_scroll_position', '0');
        navigate('/');
        setTimeout(() => {
          const newsSection = document.getElementById('news');
          if (newsSection) {
            newsSection.scrollIntoView({ behavior: 'smooth' });
          } else {
            window.scrollTo({ top: 0, behavior: 'smooth' });
          }
        }, 100);
      }
    },
    {
      label: '资讯',
      icon: <Newspaper className="w-4 h-4" />,
      onClick: () => navigate('/news')
    },
    { label: news?.title }
  ];

  if (loading) {
    return (
      <div className="min-h-screen bg-[#0a0a0f] flex items-center justify-center">
        <div className="animate-spin w-8 h-8 border-2 border-purple-500 border-t-transparent rounded-full" />
      </div>
    );
  }

  if (error || !news) {
    return (
      <div className="min-h-screen bg-[#0a0a0f] flex items-center justify-center">
        <div className="text-center">
          <p className="text-white/60 mb-4">{error || '资讯不存在'}</p>
          <button onClick={() => navigate('/news')} className="text-purple-400 hover:text-purple-300">
            返回资讯列表
          </button>
        </div>
      </div>
    );
  }

  return (
    <PageLayout breadcrumbs={breadcrumbs}>
      <article className="max-w-4xl mx-auto px-6">
        {/* 返回按钮 */}
        <motion.div
          initial={{ opacity: 0, x: -20 }}
          animate={{ opacity: 1, x: 0 }}
          className="mb-6"
        >
          <button
            onClick={() => {
              // 检查是否有来源信息
              const fromPage = sessionStorage.getItem('newslist_page');
              if (fromPage) {
                navigate('/news');
              } else {
                // 如果没有缓存，返回首页资讯区块
                sessionStorage.setItem('home_scroll_position', '0');
                navigate('/');
                setTimeout(() => {
                  const newsSection = document.getElementById('news');
                  if (newsSection) {
                    newsSection.scrollIntoView({ behavior: 'smooth' });
                  }
                }, 100);
              }
            }}
            className="inline-flex items-center gap-2 text-white/60 hover:text-white transition-colors group"
          >
            <ArrowLeft className="w-5 h-5 transition-transform group-hover:-translate-x-1" />
            <span>返回资讯列表</span>
          </button>
        </motion.div>

        {/* 资讯头部 */}
        <motion.header
          initial={{ opacity: 0, y: 20 }}
          animate={{ opacity: 1, y: 0 }}
          className="mb-12"
        >
          {/* 分类 */}
          <div className="flex flex-wrap items-center gap-2 mb-4">
            <span className="inline-block px-3 py-1 text-sm font-medium rounded-full bg-purple-500/20 text-purple-400">
              {news.category || '技术动态'}
            </span>
          </div>

          {/* 标题 */}
          <h1 className="text-3xl md:text-5xl font-bold text-white mb-6 leading-tight">
            {news.title}
          </h1>

          {/* 元信息 */}
          <div className="flex flex-wrap items-center gap-6 text-white/50 text-sm">
            <span className="flex items-center gap-2">
              <span className="text-white/80">{news.source || '未知来源'}</span>
            </span>
            <span className="flex items-center gap-2">
              <Calendar className="w-4 h-4" />
              {formatDateShort(news.created_at)}
            </span>
            <span className="flex items-center gap-2">
              {formatRelativeTime(news.created_at)}
            </span>
            <span className="flex items-center gap-2">
              浏览: {formatViews(news.views)}
            </span>
          </div>
        </motion.header>

        {/* 外部来源提示 */}
        {news.url && (
          <motion.div
            initial={{ opacity: 0 }}
            animate={{ opacity: 1 }}
            transition={{ delay: 0.15 }}
            className="mb-8 flex items-center gap-3 px-4 py-3 rounded-xl bg-blue-500/10 border border-blue-500/20"
          >
            <ExternalLink className="w-4 h-4 text-blue-400 flex-shrink-0" />
            <span className="text-blue-300/80 text-sm">
              本文转载自外部来源，内容以原文为准
            </span>
            <a
              href={news.url}
              target="_blank"
              rel="noopener noreferrer"
              className="ml-auto inline-flex items-center gap-1.5 px-3 py-1.5 rounded-lg bg-blue-500/20 text-blue-400 hover:bg-blue-500/30 transition-colors text-sm font-medium flex-shrink-0"
            >
              查看原文
              <ExternalLink className="w-3.5 h-3.5" />
            </a>
          </motion.div>
        )}

        {/* 资讯内容 */}
        <motion.div
          initial={{ opacity: 0, y: 20 }}
          animate={{ opacity: 1, y: 0 }}
          transition={{ delay: 0.3 }}
          className="prose prose-invert prose-lg max-w-none"
        >
          {news.content ? (
            <div
              className="text-white/80 leading-relaxed whitespace-pre-wrap [&>p]:mb-4 [&>p]:leading-relaxed [&_h1]:text-3xl [&_h1]:font-bold [&_h1]:text-white [&_h1]:mt-10 [&_h1]:mb-6 [&_h2]:text-2xl [&_h2]:font-bold [&_h2]:text-white [&_h2]:mt-8 [&_h2]:mb-4 [&_h3]:text-xl [&_h3]:font-bold [&_h3]:text-white [&_h3]:mt-6 [&_h3]:mb-3 [&_p]:text-white/80 [&_p]:leading-relaxed [&_p]:mb-4 [&_a]:text-purple-400 [&_a:hover]:text-purple-300 [&_ul]:list-disc [&_ul]:ml-6 [&_ul]:mb-4 [&_ul]:text-white/80 [&_ol]:list-decimal [&_ol]:ml-6 [&_ol]:mb-4 [&_ol]:text-white/80 [&_li]:mb-2 [&_blockquote]:border-l-4 [&_blockquote]:border-purple-500 [&_blockquote]:pl-4 [&_blockquote]:italic [&_blockquote]:text-white/60 [&_blockquote]:my-4 [&_pre]:bg-white/5 [&_pre]:rounded-lg [&_pre]:p-4 [&_pre]:my-4 [&_pre]:overflow-x-auto [&_code]:text-sm [&_code]:text-green-400 [&_img]:rounded-lg [&_img]:my-4 [&_strong]:font-bold [&_strong]:text-white [&_em]:italic"
              dangerouslySetInnerHTML={{ __html: DOMPurify.sanitize(/<[a-z][\s\S]*>/i.test(news.content) ? news.content : news.content.replace(/\n/g, '<br/>')) }}
            />
          ) : (
            <div className="text-white/60 text-center py-16">
              <div className="w-16 h-16 mx-auto mb-4 rounded-full bg-white/5 flex items-center justify-center">
                <Newspaper className="w-8 h-8 text-white/30" />
              </div>
              <p className="text-lg mb-2">该资讯暂无详细内容</p>
              <p className="text-sm text-white/40 mb-6">资讯来源于外部平台，仅提供标题和摘要信息</p>
              {news.url && (
                <a
                  href={news.url}
                  target="_blank"
                  rel="noopener noreferrer"
                  className="inline-flex items-center gap-2 px-6 py-3 rounded-xl bg-purple-500/20 text-purple-400 hover:bg-purple-500/30 transition-colors font-medium"
                >
                  <ExternalLink className="w-4 h-4" />
                  查看原文
                </a>
              )}
            </div>
          )}
        </motion.div>

        {/* 操作按钮 */}
        <motion.div
          initial={{ opacity: 0 }}
          animate={{ opacity: 1 }}
          transition={{ delay: 0.5 }}
          className="mt-12 pt-8 border-t border-white/10 flex items-center justify-between flex-wrap gap-4"
        >
          {news.url && (
            <a
              href={news.url}
              target="_blank"
              rel="noopener noreferrer"
              className="flex items-center gap-2 px-4 py-2 rounded-lg bg-purple-500/20 text-purple-400 hover:bg-purple-500/30 transition-colors"
            >
              <ExternalLink className="w-4 h-4" />
              <span>查看原文</span>
            </a>
          )}

          <div className="flex items-center gap-4">
            <button
              onClick={async () => {
                try {
                  await navigator.clipboard.writeText(window.location.href);
                  setCopySuccess(true);
                  setTimeout(() => setCopySuccess(false), 2000);
                } catch {
                  // 降级方案
                  const textArea = document.createElement('textarea');
                  textArea.value = window.location.href;
                  document.body.appendChild(textArea);
                  textArea.select();
                  document.execCommand('copy');
                  document.body.removeChild(textArea);
                  setCopySuccess(true);
                  setTimeout(() => setCopySuccess(false), 2000);
                }
              }}
              className="flex items-center gap-2 px-4 py-2 rounded-lg bg-white/5 text-white/60 hover:text-white hover:bg-white/10 transition-colors"
            >
              <Share2 className="w-4 h-4" />
              <span>分享</span>
              {copySuccess && <span className="text-green-400 text-sm ml-2">已复制</span>}
            </button>
          </div>
        </motion.div>

        {/* 版权声明 */}
        <motion.div
          initial={{ opacity: 0 }}
          animate={{ opacity: 1 }}
          transition={{ delay: 0.6 }}
          className="mt-12 p-6 rounded-2xl bg-white/5 border border-white/10"
        >
          <p className="text-white/60 text-sm">
            <strong className="text-white">文章来源：</strong>
            {news.source || '互联网'} · {formatDate(news.created_at)}
          </p>
          <p className="text-white/40 text-xs mt-2">
            本文仅供学习交流，如有侵权请联系删除。
          </p>
        </motion.div>
      </article>
    </PageLayout>
  );
}
