import { useState, useEffect } from 'react';
import { Link } from 'react-router-dom';
import { motion } from 'framer-motion';
import { Search, ExternalLink, Wrench, Home } from 'lucide-react';
import { supabase } from '../lib/supabase';
import PageLayout from '../components/PageLayout';

const ToolsList = () => {
  const [tools, setTools] = useState([]);
  const [loading, setLoading] = useState(true);
  const [searchKeyword, setSearchKeyword] = useState('');
  const [activeCategory, setActiveCategory] = useState('全部');

  useEffect(() => {
    loadTools();
  }, []);

  const loadTools = async () => {
    try {
      const { data, error } = await supabase
        .from('tools')
        .select('*')
        .or('status.eq.active,status.is.null')
        .order('sort_order', { ascending: true });
      if (error) throw error;
      setTools(data || []);
    } catch (err) {
      console.error('Load tools error:', err);
      setTools([]);
    }
    setLoading(false);
  };

  const categories = ['全部', ...new Set(tools.map(t => t.category).filter(Boolean))];

  const filteredTools = tools.filter(tool => {
    const matchSearch = !searchKeyword ||
      tool.name?.toLowerCase().includes(searchKeyword.toLowerCase()) ||
      tool.description?.toLowerCase().includes(searchKeyword.toLowerCase());
    const matchCategory = activeCategory === '全部' || tool.category === activeCategory;
    return matchSearch && matchCategory;
  });

  return (
    <PageLayout title="工具箱" breadcrumbs={[{ name: '首页', path: '/' }, { name: '工具箱' }]}>
      <div className="max-w-6xl mx-auto px-4 sm:px-6 lg:px-8 py-12">
        <motion.div
          initial={{ opacity: 0, y: 20 }}
          animate={{ opacity: 1, y: 0 }}
          className="text-center mb-10"
        >
          <h1 className="text-4xl font-bold mb-4">
            <span className="bg-gradient-to-r from-purple-400 to-pink-400 bg-clip-text text-transparent">工具箱</span>
          </h1>
          <p className="text-white/60">精选实用工具，提升开发效率</p>
        </motion.div>

        {/* 搜索和筛选 */}
        <motion.div
          initial={{ opacity: 0, y: 10 }}
          animate={{ opacity: 1, y: 0 }}
          transition={{ delay: 0.1 }}
          className="flex flex-col sm:flex-row gap-4 mb-8"
        >
          <div className="relative flex-1">
            <Search className="absolute left-3 top-1/2 -translate-y-1/2 w-4 h-4 text-white/40" />
            <input
              type="text"
              value={searchKeyword}
              onChange={(e) => setSearchKeyword(e.target.value)}
              placeholder="搜索工具..."
              className="w-full pl-10 pr-4 py-2.5 rounded-xl bg-white/5 border border-white/10 text-white text-sm placeholder-white/30 focus:outline-none focus:border-purple-500/50"
            />
          </div>
          <div className="flex gap-2 flex-wrap">
            {categories.map(cat => (
              <button
                key={cat}
                onClick={() => setActiveCategory(cat)}
                className={`px-4 py-2 rounded-xl text-sm transition-all ${
                  activeCategory === cat
                    ? 'bg-purple-500/20 text-purple-400 border border-purple-500/30'
                    : 'bg-white/5 text-white/60 border border-white/10 hover:bg-white/10'
                }`}
              >
                {cat}
              </button>
            ))}
          </div>
        </motion.div>

        {loading ? (
          <div className="flex items-center justify-center py-20">
            <div className="animate-spin w-8 h-8 border-2 border-purple-500 border-t-transparent rounded-full" />
          </div>
        ) : filteredTools.length === 0 ? (
          <div className="text-center py-20 text-white/40">
            <Wrench className="w-16 h-16 mx-auto mb-4 opacity-30" />
            <p className="text-lg">暂无工具</p>
          </div>
        ) : (
          <div className="grid grid-cols-1 sm:grid-cols-2 lg:grid-cols-3 xl:grid-cols-4 gap-6">
            {filteredTools.map((tool, index) => (
              <motion.a
                key={tool.id}
                href={tool.url || '#'}
                target="_blank"
                rel="noopener noreferrer"
                initial={{ opacity: 0, y: 20 }}
                animate={{ opacity: 1, y: 0 }}
                transition={{ duration: 0.4, delay: index * 0.03 }}
                className="group bg-white/5 backdrop-blur-sm rounded-2xl border border-white/10 p-6 hover:bg-white/10 hover:border-purple-500/30 transition-all duration-300 hover:-translate-y-1"
              >
                <div className="text-4xl mb-4">{tool.icon || '🔧'}</div>
                <h3 className="text-lg font-semibold text-white mb-2 group-hover:text-purple-400 transition-colors">
                  {tool.name}
                </h3>
                <p className="text-white/50 text-sm mb-3 line-clamp-2">{tool.description || '暂无描述'}</p>
                {tool.category && (
                  <span className="inline-block px-2 py-1 rounded-full bg-white/10 text-white/50 text-xs mb-3">
                    {tool.category}
                  </span>
                )}
                <div className="flex items-center text-purple-400 text-sm">
                  <span>使用工具</span>
                  <ExternalLink className="w-4 h-4 ml-1" />
                </div>
              </motion.a>
            ))}
          </div>
        )}
      </div>
    </PageLayout>
  );
};

export default ToolsList;
